-- Gemini Notebook (NotebookLM) — Дослідження та пошук
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'notebook.google' OR LOWER(`name`) = LOWER('Gemini Notebook (NotebookLM)'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Gemini Notebook (NotebookLM)', NULL, 'https://notebook.google', NULL, NULL, 'AI-помічник Google для досліджень на ваших джерелах (колишній NotebookLM): відповідає лише на основі завантажених документів, робить аудіопереказ, відеоогляди та ментальні карти.', 'Google''s AI research assistant grounded in your own sources (formerly NotebookLM): it answers only from the documents you add and creates audio overviews, video overviews and mind maps.', 'Gemini Notebook — так тепер називається NotebookLM, інструмент Google для роботи з власними джерелами. У блокнот додають документи, PDF, сайти, відео чи нотатки, і AI на основі моделей Gemini відповідає на запитання, посилаючись саме на ці матеріали, а не на інтернет загалом. Він уміє робити інтерактивні аудіоперекази у форматі розмови, відеоогляди, ментальні карти, конспекти й навчальні матеріали. Є добірка публічних блокнотів, з яких можна почати. Працює у вебі та в мобільних застосунках. Базові можливості безкоштовні; розширені ліміти доступні в планах Google AI Plus, AI Pro та AI Ultra (в Україні AI Pro — ₴909,99 на місяць).', 'Gemini Notebook is the new name of NotebookLM, Google''s tool for working with your own sources. You add documents, PDFs, websites, videos or notes to a notebook, and AI built on Gemini models answers questions citing exactly those materials rather than the web at large. It can create interactive audio overviews in a conversation format, video overviews, mind maps, summaries and study materials. A collection of public notebooks helps you get started. It works on the web and in mobile apps. Core features are free; higher limits come with the Google AI Plus, AI Pro and AI Ultra plans (AI Pro costs ₴909.99 a month in Ukraine).', 'Відповіді лише на основі ваших джерел із посиланнями
Аудіопереказ у форматі розмови
Відеоогляди й ментальні карти
Конспекти та навчальні матеріали
Веб і мобільні застосунки', 'Answers grounded only in your sources, with citations
Audio overviews in a conversation format
Video overviews and mind maps
Summaries and study materials
Web and mobile apps', 'Студенти, дослідники, журналісти й аналітики, які працюють з великою кількістю власних матеріалів.', 'Students, researchers, journalists and analysts who work with large sets of their own materials.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
SET @pid = (SELECT `id` FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'notebook.google' OR LOWER(`name`) = LOWER('Gemini Notebook (NotebookLM)')) ORDER BY `id` LIMIT 1);
