-- Kagi — Дослідження та пошук
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'kagi.com' OR LOWER(`name`) = LOWER('Kagi'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Kagi', NULL, 'https://kagi.com', NULL, NULL, 'Платна пошукова система без реклами й стеження, з AI-асистентом: якісна видача, налаштування сайтів у результатах і режим глибокого дослідження з провідними моделями.', 'A paid search engine with no ads or tracking and an AI assistant: high-quality results, control over which sites rank, and a research mode with leading models.', 'Kagi — пошукова система, яку фінансують самі користувачі, тому в ній немає реклами, трекінгу та SEO-сміття. Видачу можна налаштовувати: підвищувати, знижувати чи блокувати окремі сайти, використовувати лінзи для тематичного пошуку. Kagi Assistant дає доступ до моделей Claude, GPT, Gemini та інших, з режимами швидкої відповіді й глибокого дослідження з джерелами. Тарифи: пробний — безкоштовно 100 пошуків; Starter — $5 на місяць (300 пошуків); Professional — $10 на місяць (необмежений пошук); Ultimate — $25 на місяць (необмежений пошук, режим Research і преміальні моделі). Річна оплата дешевша на 10%, а в місяці без використання гроші не списуються.', 'Kagi is a search engine funded by its users, so it has no ads, tracking or SEO spam. You can tune results: raise, lower or block specific sites and use lenses for topic-focused search. Kagi Assistant gives access to Claude, GPT, Gemini and other models, with quick-answer and in-depth research modes with sources. Plans: Trial — 100 free searches; Starter — $5 a month (300 searches); Professional — $10 a month (unlimited search); Ultimate — $25 a month (unlimited search, Research mode and premium models). Annual billing is 10% cheaper, and you are not charged in months without usage.', 'Пошук без реклами й трекінгу
Налаштування сайтів у видачі та лінзи
Kagi Assistant з Claude, GPT, Gemini
Режим глибокого дослідження з джерелами', 'Search with no ads or tracking
Site ranking controls and lenses
Kagi Assistant with Claude, GPT, Gemini
In-depth research mode with sources', 'Ті, кому важлива приватність і якісна видача без реклами: розробники, дослідники, журналісти.', 'People who value privacy and clean, ad-free results: developers, researchers and journalists.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
