-- scite — Дослідження та пошук
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'scite.ai' OR LOWER(`name`) = LOWER('scite'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'scite', NULL, 'https://scite.ai', NULL, NULL, 'AI-асистент для наукових досліджень зі Smart Citations: показує, чи підтверджують наступні роботи висновки статті, чи заперечують їх, і відповідає з посиланнями на джерела.', 'An AI research assistant with Smart Citations: it shows whether later studies support or contradict a paper''s findings and answers with references to sources.', 'scite допомагає знаходити й оцінювати наукову літературу. Його головна особливість — Smart Citations: для кожної статті видно, у якому контексті її цитують і чи підтверджують наступні дослідження її висновки, чи суперечать їм. База охоплює понад 1,6 млрд цитувань із більш ніж 300 млн наукових джерел. AI-асистент відповідає на запитання з посиланнями на реальні статті, є пошук, колекції статей, API та доступ через MCP для інших AI-інструментів. Тарифи: Connect — безкоштовно (лише MCP); Basic — $20 на місяць ($240 на рік); Pro — $50 на місяць ($600 на рік, з API). Для Basic і Pro є 7-денний пробний період.', 'scite helps you find and evaluate scientific literature. Its key feature is Smart Citations: for each paper you see the context in which it is cited and whether later studies support or contradict its findings. The database covers more than 1.6 billion citations from over 300 million scholarly sources. The AI assistant answers questions with references to real papers, and there is search, paper collections, an API and MCP access for other AI tools. Plans: Connect — free (MCP only); Basic — $20 a month ($240 a year); Pro — $50 a month ($600 a year, with API). Basic and Pro have a 7-day free trial.', 'Smart Citations: підтверджує чи заперечує
1,6 млрд+ цитувань із 300 млн+ джерел
AI-асистент з посиланнями на статті
Колекції статей, API та MCP', 'Smart Citations: supporting or contrasting
1.6B+ citations from 300M+ sources
AI assistant with references to papers
Paper collections, API and MCP', 'Науковці, аспіранти, студенти й медичні фахівці, яким потрібна перевірена наукова база.', 'Scientists, PhD students, students and medical professionals who need a verified evidence base.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
