-- Undermind — Дослідження та пошук
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'undermind.ai' OR LOWER(`name`) = LOWER('Undermind'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Undermind', NULL, 'https://www.undermind.ai', NULL, NULL, 'AI-агент для пошуку наукових статей: уточнює ваше запитання, ретельно перебирає літературу й знаходить найрелевантніші роботи, з якими далі можна працювати глибше.', 'An AI agent for finding scientific papers: it clarifies your question, searches the literature thoroughly and finds the most relevant work, which you can then explore in depth.', 'Undermind — дослідницький AI-агент для наукової літератури. Спершу він ставить уточнювальні запитання, щоб зрозуміти, що саме ви шукаєте, а потім систематично перебирає публікації, читає їх і повертає впорядкований список найрелевантніших робіт з поясненнями. За тестами компанії, за 10 хвилин він знаходить 85% з двадцяти найважливіших статей, тоді як інші AI-агенти пошуку — близько половини. Сервіс інтегрується з Claude, ChatGPT та іншими інструментами, ним користуються науковці MIT, Гарварду, Caltech та фармацевтичних компаній. Тарифи: Free; Pro — $16 на місяць при річній оплаті (повнотекстовий аналіз, у 10 разів вищі ліміти); Team — $15 на людину на місяць; Enterprise — за запитом.', 'Undermind is a research AI agent for scientific literature. It first asks clarifying questions to understand exactly what you are looking for, then systematically works through publications, reads them and returns a ranked list of the most relevant papers with explanations. In the company''s benchmarks it finds 85% of the 20 most relevant papers within 10 minutes, compared with about half for other AI search agents. It integrates with Claude, ChatGPT and other tools and is used by scientists at MIT, Harvard, Caltech and pharmaceutical companies. Plans: Free; Pro at $16 a month billed annually (full-text analysis, 10× higher limits); Team at $15 per person a month; Enterprise on request.', 'Уточнювальні запитання перед пошуком
Систематичний перебір і читання статей
Повнотекстовий аналіз (Pro)
Інтеграція з Claude, ChatGPT та іншими', 'Clarifying questions before the search
Systematic search and reading of papers
Full-text analysis (Pro)
Integration with Claude, ChatGPT and more', 'Науковці, інженери й R&D-команди, яким потрібен вичерпний пошук літератури.', 'Scientists, engineers and R&D teams who need an exhaustive literature search.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
