-- Exa — Дослідження та пошук
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'exa.ai' OR LOWER(`name`) = LOWER('Exa'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Exa', NULL, 'https://exa.ai', NULL, NULL, 'Пошуковий API для AI-застосунків: швидкий пошук в інтернеті, вміст сторінок у зручному для моделей вигляді, готові відповіді та глибоке дослідження за запитом.', 'A search API for AI applications: fast web search, page contents in a model-friendly format, ready answers and in-depth research on demand.', 'Exa — пошукова система, створена для AI: замість сторінки з посиланнями розробники отримують через API релевантні результати та текст сторінок у компактному вигляді, зручному для мовних моделей. Є кілька режимів — миттєвий, швидкий і глибокий пошук, — а також Answer для готових відповідей з джерелами, Monitors для відстеження нових публікацій і Agent для багатокрокових досліджень. Оплата за використання: щомісяця $10 безкоштовних кредитів (≈2 500 швидких пошуків), далі — від $4 за 1 000 пошуків, $1 за 1 000 сторінок контенту, $5 за 1 000 відповідей. Для великих обсягів є Enterprise з власними індексами та нульовим зберіганням даних.', 'Exa is a search engine built for AI: instead of a page of links, developers get relevant results and page text through an API in a compact format suited to language models. There are several modes — instant, fast and deep search — plus Answer for ready answers with sources, Monitors for tracking new publications and Agent for multi-step research. Pricing is pay-as-you-go: $10 in free credits every month (≈2,500 instant searches), then from $4 per 1,000 searches, $1 per 1,000 pages of contents and $5 per 1,000 answers. Enterprise is available for high volumes, with custom indexes and zero data retention.', 'Пошуковий API з миттєвим, швидким і глибоким режимами
Текст сторінок у форматі для LLM
Answer, Monitors і Agent
$10 безкоштовних кредитів щомісяця', 'Search API with instant, fast and deep modes
Page contents in an LLM-friendly format
Answer, Monitors and Agent
$10 in free credits every month', 'Розробники AI-агентів, чат-ботів і RAG-систем, яким потрібен доступ до актуального інтернету.', 'Developers of AI agents, chatbots and RAG systems that need access to the live web.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
