SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'you.com' OR LOWER(`name`) = LOWER('You.com'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'You.com', NULL, 'https://you.com', NULL, NULL, 'API для пошуку й досліджень, створені для AI-систем і компаній: актуальна видача, витягування тексту зі сторінок і відповіді з посиланнями на джерела.', 'Search and research APIs built for AI systems and enterprises: real-time results, text extraction from pages and answers with citations.', 'You.com розвивається як платформа пошукових і дослідницьких API для AI-систем. Web Search API повертає актуальні результати (до 100 посилань за запит), Contents API витягує текст із кількох сторінок, Answer API дає узагальнені відповіді з посиланнями на джерела, Research API — розгорнуті дослідження, а Finance Research API — дані про компанії, звітність і ринки. Для компаній доступні нульове зберігання даних, сертифікація SOC 2 та індивідуальні ліміти. Безкоштовний рівень: 100 запитів на день і $100 кредиту; далі оплата за 1 000 викликів — $5 за пошук, $1 за контент, $5 за відповіді, $12 за дослідження.', 'You.com has evolved into a platform of search and research APIs for AI systems. The Web Search API returns real-time results (up to 100 URLs per call), the Contents API extracts text from multiple pages, the Answer API gives synthesised answers with citations, the Research API delivers in-depth research and the Finance Research API provides company data, filings and market research. Enterprises get zero data retention, SOC 2 certification and custom rate limits. The free tier offers 100 queries a day and $100 in credit; after that pricing per 1,000 calls is $5 for search, $1 for contents, $5 for answers and $12 for research.', 'Web Search API з актуальною видачею
Витягування тексту сторінок (Contents API)
Відповіді й дослідження з посиланнями
Нульове зберігання даних і SOC 2', 'Web Search API with real-time results
Page text extraction (Contents API)
Answers and research with citations
Zero data retention and SOC 2', 'Розробники та компанії, що будують AI-продукти з доступом до інтернету.', 'Developers and companies building AI products with web access.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
